use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::Mutex;
use std::collections::HashMap;

#[derive(Clone, Serialize, Deserialize)]
struct TokenGrant {
    user_id: String,
    scope: String,
    expires_at: u64,
}

#[derive(Clone)]
struct AppState {
    // Tracks issued token count per user for rate limiting
    token_counter: Arc<Mutex<HashMap<String, u32>>>,
    // HSM session handle (opaque reference)
    hsm_session: Arc<HsmSession>,
}

struct HsmSession {
    slot_id: u64,
    session_handle: u64,
}

impl HsmSession {
    fn new() -> Self {
        // In production, this calls C_OpenSession via PKCS#11
        HsmSession { slot_id: 1, session_handle: 0xDEAD } 
    }

    async fn sign_token(&self, payload: &[u8]) -> Vec<u8> {
        // Calls C_Sign on the HSM - key never leaves hardware
        // Simulated: in real deployment this is a PKCS#11 FFI call
        let mut sig = vec![0u8; 64];
        sig[..payload.len().min(64)].copy_from_slice(&payload[..payload.len().min(64)]);
        sig
    }
}

async fn issue_token(
    state: web::Data<AppState>,
    grant: web::Json<TokenGrant>,
) -> HttpResponse {
    let user_id = grant.user_id.clone();

    // RACE CONDITION: check-then-act on token_counter is not atomic
    // Between the read and the write, concurrent requests can bypass the limit
    let current_count = {
        let counter = state.token_counter.lock().await;
        *counter.get(&user_id).unwrap_or(&0)
    };
    // Lock is released here ^

    // Rate limit: max 5 tokens per user
    if current_count >= 5 {
        return HttpResponse::TooManyRequests().json(serde_json::json!({
            "error": "token_limit_exceeded",
            "max": 5
        }));
    }

    // Simulate some async work (signing via HSM)
    let payload = serde_json::to_vec(&grant.into_inner()).unwrap();
    let _signature = state.hsm_session.sign_token(&payload).await;

    // TOCTOU gap: re-acquire lock and increment
    {
        let mut counter = state.token_counter.lock().await;
        let entry = counter.entry(user_id.clone()).or_insert(0);
        *entry += 1;
    }

    // In a real app, the signed token would be returned
    HttpResponse::Ok().json(serde_json::json!({
        "token": "signed_opaque_token",
        "user": user_id,
        "count": current_count + 1
    }))
}

async fn revoke_all(
    state: web::Data<AppState>,
    user: web::Json<serde_json::Value>,
) -> HttpResponse {
    let user_id = user.get("user_id").and_then(|v| v.as_str()).unwrap_or("");
    let mut counter = state.token_counter.lock().await;
    counter.remove(user_id);
    HttpResponse::Ok().json(serde_json::json!({"revoked": true}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let state = AppState {
        token_counter: Arc::new(Mutex::new(HashMap::new())),
        hsm_session: Arc::new(HsmSession::new()),
    };

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/token/issue", web::post().to(issue_token))
            .route("/token/revoke", web::post().to(revoke_all))
    })
    .workers(8)
    .bind("0.0.0.0:8443")?
    .run()
    .await
}
